package com.ssverma.common.ui.a2ui.component

import androidx.compose.foundation.layout.padding
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import com.ssverma.core.ui.theme.spacing
import com.ssverma.shared.ai.a2ui.model.A2UiComponent

/**
 * Renders textual narrative generated by the on-device AI Agent.
 */
@Composable
fun A2UiTextRenderer(
    textComponent: A2UiComponent.Text,
    modifier: Modifier = Modifier
) {
    Text(
        text = textComponent.content,
        style = if (textComponent.isEmphasized) {
            MaterialTheme.typography.titleMedium
        } else {
            MaterialTheme.typography.bodyLarge
        },
        color = if (textComponent.isEmphasized) {
            MaterialTheme.colorScheme.primary
        } else {
            MaterialTheme.colorScheme.onSurface
        },
        modifier = modifier.padding(vertical = MaterialTheme.spacing.small)
    )
}
